import fs from 'node:fs';
const {input} = JSON.parse(fs.readFileSync(0, 'utf8'));
const values = input.values;
if (!Array.isArray(values) || values.length < 1 || values.length > 100 || !values.every(v => typeof v === 'number' && Number.isFinite(v))) throw new Error('values must contain 1 to 100 finite numbers');
const sum = values.reduce((a, b) => a + b, 0);
if (!Number.isFinite(sum)) throw new Error('sum must be finite');
process.stdout.write(JSON.stringify({count: values.length, sum, mean: sum / values.length}));

